		prevPlusDM -= float64(prevPlusDM * invPeriod)
		minusSel = selF(diffM-diffP > 0.0, diffM, 0.0)
		plusSel = selF(diffP-diffM > 0.0, diffP, 0.0)
		minusDM1 = selF(diffM > 0.0, minusSel, 0.0)
		plusDM1 = selF(diffP > 0.0, plusSel, 0.0)
